package com.dndmaster.combatmap.api;
import java.util.Objects; import java.util.UUID;
public final class ApiRequestGuard { private final String internalToken; public ApiRequestGuard(String token){internalToken=required(token,"internal token");}public void publicOwner(String bearer,UUID principal,UUID owner){if(bearer==null||bearer.isBlank())throw new ApiContractException(401,"UNAUTHENTICATED");if(!Objects.requireNonNull(principal).equals(Objects.requireNonNull(owner)))throw new ApiContractException(403,"OWNERSHIP_DENIED");}public void internal(String token){if(!internalToken.equals(token))throw new ApiContractException(401,"INVALID_SERVICE_TOKEN");}public static String required(String value,String field){if(value==null||value.isBlank())throw new ApiContractException(400,"INVALID_"+field.toUpperCase().replace(' ','_'));return value.trim();}public static final class ApiContractException extends RuntimeException{private final int status;private final String code;public ApiContractException(int status,String code){super(code);this.status=status;this.code=code;}public int status(){return status;}public String code(){return code;}}}
